-- Phase 6: "Listen" audio generated by the admin (never by readers).
-- One row per article + locale: the WAV file's path in the "article-audio" Storage bucket, its size and length,
-- the voice, and the SHA-256 of the text it reads (source_hash). When the article's text changes the audio is
-- out of date and is no longer offered to readers until the admin regenerates it. Rows go with the article.
CREATE TABLE "ai_audio" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"article_id" uuid NOT NULL,
	"locale" "locale" NOT NULL,
	"path" text NOT NULL,
	"bytes" integer NOT NULL,
	"duration_ms" integer NOT NULL,
	"voice" text NOT NULL,
	"source_hash" text NOT NULL,
	"source_updated_at" timestamp with time zone NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "ai_audio_article_id_locale_unique" UNIQUE("article_id","locale")
);
